export function getFinancialReportData(periodeType = 'harian', selectorValue = '16 Oktober 2026') {
  if (periodeType === 'harian') {
    const found = DAILY_FINANCIAL_DATA[selectorValue];
    if (found) {
      return {
        periodeType: 'harian',
        periodeLabel: selectorValue,
        tanggalCetak: selectorValue,
        summary: found.summary,
        pemasukan: found.pemasukan,
        pengeluaran: found.pengeluaran,
        topPengeluaran: found.topPengeluaran,
      };
    }
    return {
      periodeType: 'harian',
      periodeLabel: selectorValue || '16 Oktober 2026',
      tanggalCetak: selectorValue || '16 Oktober 2026',
      summary: { omzet: 0, pengeluaran: 0, labaBersih: 0 },
      pemasukan: [],
      pengeluaran: [],
      topPengeluaran: [],
    };
  }

  if (periodeType === 'bulanan') {
    const found = MONTHLY_FINANCIAL_DATA[selectorValue] || MONTHLY_FINANCIAL_DATA['Oktober 2026'];
    if (found) {
      return {
        periodeType: 'bulanan',
        periodeLabel: selectorValue,
        tanggalCetak: selectorValue,
        summary: found.summary,
        pemasukan: found.pemasukan,
        pengeluaran: found.pengeluaran,
        topPengeluaran: found.topPengeluaran,
      };
    }
    return {
      periodeType: 'bulanan',
      periodeLabel: selectorValue || 'Oktober 2026',
      tanggalCetak: selectorValue || 'Oktober 2026',
      summary: { omzet: 0, pengeluaran: 0, labaBersih: 0 },
      pemasukan: [],
      pengeluaran: [],
      topPengeluaran: [],
    };
  }

  // Tahunan (Januari - Desember)
  if (periodeType === 'tahunan') {
    const foundYear = YEARLY_FINANCIAL_DATA[selectorValue] || YEARLY_FINANCIAL_DATA['2026'];
    if (foundYear) {
      return {
        periodeType: 'tahunan',
        periodeLabel: selectorValue || '2026',
        tanggalCetak: `31 Desember ${selectorValue || '2026'}`,
        summary: foundYear.summary,
        pemasukan: foundYear.pemasukan,
        pengeluaran: foundYear.pengeluaran,
        topPengeluaran: foundYear.topPengeluaran,
      };
    }
    return {
      periodeType: 'tahunan',
      periodeLabel: selectorValue || '2026',
      tanggalCetak: '31 Desember 2026',
      summary: { omzet: 0, pengeluaran: 0, labaBersih: 0 },
      pemasukan: [],
      pengeluaran: [],
      topPengeluaran: [],
    };
  }

  return getFinancialReportData('harian', '16 Oktober 2026');
}

export const FINANCIAL_REPORT_DATA = {
  harian: getFinancialReportData('harian', '16 Oktober 2026'),
  bulanan: getFinancialReportData('bulanan', 'Oktober 2026'),
  tahunan: getFinancialReportData('tahunan', '2026'),
};
